import sys

s = sys.stdin.read().split()[0]
n = int(s)
L = len(s)

def is_pal(x):
    t = str(x)
    return t == t[::-1]

if n < 10 ** 7:
    d = 1
    while True:
        if n - d >= 0 and is_pal(n - d):
            print(n - d)
            break
        if is_pal(n + d):
            print(n + d)
            break
        d += 1
else:
    pre = int(s[:(L + 1) // 2])
    best = None
    pals = [0, 10 ** (L - 1) - 1, 10 ** L + 1, 10 ** (L - 1) + 1, 10 ** L - 1]
    for h in range(pre - 5, pre + 6):
        if h < 1:
            continue
        t = str(h)
        pals.append(int(t + t[::-1]))
        pals.append(int(t + t[-2::-1]))
    for x in pals:
        if x != n and is_pal(x):
            key = (abs(x - n), x)
            if best is None or key < best:
                best = key
    print(best[1])

